    INSERT INTO "__SCHEMA__".content_version
      (content_version_id, kind, family, source_path, review_status, rights_status, content_sha256, exam_id)
    VALUES
    ('telc-deutsch-b1.vocab@v1', 'lexicon', 'vocab', 'data/vocab.json', 'unreviewed', 'unknown', '5c9563f11ce992d1d07fd8d2702d0f82d36ec95f80b8d3d7fa7ac5f8d00ce5e0', 'telc-deutsch-b1')
    INSERT INTO "__SCHEMA__".vocab_entry
      (entry_id, exam_id, ordinal, de, en, pos, plural, example, example_en, content_version_id)
    VALUES
    ('telc-deutsch-b1.vocab.der-verwandte', 'telc-deutsch-b1', 0, 'der Verwandte', 'relative', 'noun', 'die Verwandten', 'Meine Verwandten wohnen alle in Süddeutschland.', 'All my relatives live in southern Germany.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-erziehung', 'telc-deutsch-b1', 1, 'die Erziehung', 'upbringing, parenting', 'noun', 'die Erziehungen', 'Die Erziehung der Kinder ist Aufgabe der Eltern.', 'Bringing up children is the parents'' responsibility.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-ehemann', 'telc-deutsch-b1', 2, 'der Ehemann', 'husband', 'noun', 'die Ehemänner', 'Ihr Ehemann arbeitet als Ingenieur bei einer großen Firma.', 'Her husband works as an engineer at a large company.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ehefrau', 'telc-deutsch-b1', 3, 'die Ehefrau', 'wife', 'noun', 'die Ehefrauen', 'Seine Ehefrau kommt aus Österreich.', 'His wife comes from Austria.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-nachbar', 'telc-deutsch-b1', 4, 'der Nachbar', 'neighbour', 'noun', 'die Nachbarn', 'Unser Nachbar hilft uns oft im Garten.', 'Our neighbour often helps us in the garden.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-ehepaar', 'telc-deutsch-b1', 5, 'das Ehepaar', 'married couple', 'noun', 'die Ehepaare', 'Das Ehepaar Müller hat zwei Kinder und einen Hund.', 'The Müllers are a married couple with two children and a dog.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-jugendliche', 'telc-deutsch-b1', 6, 'der Jugendliche', 'young person, teenager', 'noun', 'die Jugendlichen', 'Viele Jugendliche verbringen zu viel Zeit am Handy.', 'Many young people spend too much time on their phones.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-erwachsene', 'telc-deutsch-b1', 7, 'der Erwachsene', 'adult', 'noun', 'die Erwachsenen', 'Erwachsene brauchen genauso viel Schlaf wie Jugendliche.', 'Adults need just as much sleep as young people.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-verhaeltnis', 'telc-deutsch-b1', 8, 'das Verhältnis', 'relationship, ratio', 'noun', 'die Verhältnisse', 'Ich habe ein gutes Verhältnis zu meinen Eltern.', 'I have a good relationship with my parents.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-beziehung', 'telc-deutsch-b1', 9, 'die Beziehung', 'relationship', 'noun', 'die Beziehungen', 'Nach zwei Jahren hat sie die Beziehung beendet.', 'After two years she ended the relationship.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-charakter', 'telc-deutsch-b1', 10, 'der Charakter', 'character', 'noun', 'die Charaktere', 'Mein Bruder hat einen ruhigen Charakter.', 'My brother has a calm character.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-eigenschaft', 'telc-deutsch-b1', 11, 'die Eigenschaft', 'quality, characteristic', 'noun', 'die Eigenschaften', 'Geduld ist eine wichtige Eigenschaft im Beruf.', 'Patience is an important quality at work.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-bekannte', 'telc-deutsch-b1', 12, 'der Bekannte', 'acquaintance', 'noun', 'die Bekannten', 'Ein Bekannter von mir arbeitet in Berlin.', 'An acquaintance of mine works in Berlin.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-freundschaft', 'telc-deutsch-b1', 13, 'die Freundschaft', 'friendship', 'noun', 'die Freundschaften', 'Unsere Freundschaft besteht schon seit der Schulzeit.', 'Our friendship goes back to our school days.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-vertrauen', 'telc-deutsch-b1', 14, 'das Vertrauen', 'trust', 'noun', 'das Vertrauen', 'Ohne Vertrauen kann eine Beziehung nicht funktionieren.', 'Without trust a relationship cannot work.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-verantwortung', 'telc-deutsch-b1', 15, 'die Verantwortung', 'responsibility', 'noun', 'die Verantwortungen', 'Als Vater trage ich die Verantwortung für meine Familie.', 'As a father I carry the responsibility for my family.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-elternteil', 'telc-deutsch-b1', 16, 'der Elternteil', 'parent', 'noun', 'die Elternteile', 'Jeder Elternteil sollte Zeit mit dem Kind verbringen.', 'Every parent should spend time with the child.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-geschwister', 'telc-deutsch-b1', 17, 'die Geschwister', 'siblings', 'noun', 'die Geschwister', 'Ich habe drei Geschwister, zwei Brüder und eine Schwester.', 'I have three siblings, two brothers and one sister.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-einzelkind', 'telc-deutsch-b1', 18, 'das Einzelkind', 'only child', 'noun', 'die Einzelkinder', 'Als Einzelkind hatte ich keine Geschwister.', 'As an only child I had no siblings.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-schwiegermutter', 'telc-deutsch-b1', 19, 'die Schwiegermutter', 'mother-in-law', 'noun', 'die Schwiegermütter', 'Meine Schwiegermutter kocht besser als ich.', 'My mother-in-law cooks better than I do.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sich-verlieben', 'telc-deutsch-b1', 20, 'sich verlieben', 'to fall in love', 'verb', NULL, 'Sie hat sich in ihren besten Freund verliebt.', 'She has fallen in love with her best friend.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.erziehen', 'telc-deutsch-b1', 21, 'erziehen', 'to bring up, to raise', 'verb', NULL, 'Meine Großmutter hat mich erzogen, weil meine Eltern viel arbeiten mussten.', 'My grandmother raised me because my parents had to work a lot.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.heiraten', 'telc-deutsch-b1', 22, 'heiraten', 'to marry', 'verb', NULL, 'Wir haben im Sommer in einer kleinen Kirche geheiratet.', 'We got married in summer in a small church.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-generation', 'telc-deutsch-b1', 23, 'die Generation', 'generation', 'noun', 'die Generationen', 'Meine Generation denkt über dieses Thema anders.', 'My generation thinks differently about this topic.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-kontakt', 'telc-deutsch-b1', 24, 'der Kontakt', 'contact', 'noun', 'die Kontakte', 'Ich habe noch guten Kontakt zu meinen alten Kollegen.', 'I still have good contact with my old colleagues.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-wohnung', 'telc-deutsch-b1', 25, 'die Wohnung', 'flat, apartment', 'noun', 'die Wohnungen', 'Wir suchen eine größere Wohnung mit Balkon.', 'We are looking for a bigger flat with a balcony.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-miete', 'telc-deutsch-b1', 26, 'die Miete', 'rent', 'noun', 'die Mieten', 'Die Miete in der Innenstadt ist sehr hoch.', 'The rent in the city centre is very high.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-vermieter', 'telc-deutsch-b1', 27, 'der Vermieter', 'landlord', 'noun', 'die Vermieter', 'Unser Vermieter hat die Miete leider erhöht.', 'Unfortunately our landlord has raised the rent.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-mieter', 'telc-deutsch-b1', 28, 'der Mieter', 'tenant', 'noun', 'die Mieter', 'Die Mieter müssen die Nebenkosten selbst bezahlen.', 'The tenants have to pay the additional costs themselves.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-nebenkosten', 'telc-deutsch-b1', 29, 'die Nebenkosten', 'additional costs, utilities', 'noun', 'die Nebenkosten', 'In den Nebenkosten sind Wasser und Heizung enthalten.', 'Water and heating are included in the additional costs.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-moebel', 'telc-deutsch-b1', 30, 'die Möbel', 'furniture', 'noun', 'die Möbel', 'Unsere neuen Möbel kommen nächste Woche.', 'Our new furniture is arriving next week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-schrank', 'telc-deutsch-b1', 31, 'der Schrank', 'wardrobe, cupboard', 'noun', 'die Schränke', 'Die Kleidung hängt im Schrank.', 'The clothes are hanging in the wardrobe.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-regal', 'telc-deutsch-b1', 32, 'das Regal', 'shelf', 'noun', 'die Regale', 'Die Bücher stehen im Regal neben dem Fenster.', 'The books are on the shelf next to the window.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-teppich', 'telc-deutsch-b1', 33, 'der Teppich', 'carpet, rug', 'noun', 'die Teppiche', 'Im Wohnzimmer liegt ein bunter Teppich.', 'There is a colourful carpet in the living room.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-heizung', 'telc-deutsch-b1', 34, 'die Heizung', 'heating', 'noun', 'die Heizungen', 'Im Winter funktioniert die Heizung oft nicht richtig.', 'In winter the heating often does not work properly.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-aufzug', 'telc-deutsch-b1', 35, 'der Aufzug', 'lift, elevator', 'noun', 'die Aufzüge', 'Der Aufzug ist leider schon wieder kaputt.', 'Unfortunately the lift is broken again.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-keller', 'telc-deutsch-b1', 36, 'der Keller', 'cellar, basement', 'noun', 'die Keller', 'Die Fahrräder stehen bei uns im Keller.', 'Our bicycles are kept in the cellar.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-balkon', 'telc-deutsch-b1', 37, 'der Balkon', 'balcony', 'noun', 'die Balkone', 'Am Abend sitzen wir gern auf dem Balkon.', 'In the evening we like sitting on the balcony.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-umzug', 'telc-deutsch-b1', 38, 'der Umzug', 'move (to a new home)', 'noun', 'die Umzüge', 'Der Umzug in die neue Wohnung war sehr anstrengend.', 'The move into the new flat was very exhausting.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.umziehen', 'telc-deutsch-b1', 39, 'umziehen', 'to move house', 'verb', NULL, 'Letztes Jahr sind wir nach Hamburg umgezogen.', 'Last year we moved to Hamburg.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-nachbarschaft', 'telc-deutsch-b1', 40, 'die Nachbarschaft', 'neighbourhood', 'noun', 'die Nachbarschaften', 'In unserer Nachbarschaft wohnen viele Familien mit Kindern.', 'Many families with children live in our neighbourhood.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-erdgeschoss', 'telc-deutsch-b1', 41, 'das Erdgeschoss', 'ground floor', 'noun', 'die Erdgeschosse', 'Unsere Wohnung liegt im Erdgeschoss.', 'Our flat is on the ground floor.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-etage', 'telc-deutsch-b1', 42, 'die Etage', 'floor, storey', 'noun', 'die Etagen', 'Wir wohnen in der dritten Etage ohne Aufzug.', 'We live on the third floor without a lift.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-einrichtung', 'telc-deutsch-b1', 43, 'die Einrichtung', 'furnishings, equipment', 'noun', 'die Einrichtungen', 'Die Einrichtung des Zimmers ist sehr modern.', 'The furnishings of the room are very modern.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.renovieren', 'telc-deutsch-b1', 44, 'renovieren', 'to renovate', 'verb', NULL, 'Wir wollen das Badezimmer im Frühling renovieren.', 'We want to renovate the bathroom in spring.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kaution', 'telc-deutsch-b1', 45, 'die Kaution', 'deposit', 'noun', 'die Kautionen', 'Für die Wohnung mussten wir eine Kaution bezahlen.', 'We had to pay a deposit for the flat.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-mietvertrag', 'telc-deutsch-b1', 46, 'der Mietvertrag', 'lease, rental agreement', 'noun', 'die Mietverträge', 'Den Mietvertrag haben wir für zwei Jahre unterschrieben.', 'We signed the lease for two years.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-wohngemeinschaft', 'telc-deutsch-b1', 47, 'die Wohngemeinschaft', 'flat share', 'noun', 'die Wohngemeinschaften', 'In der Wohngemeinschaft teilen wir uns die Küche.', 'In the flat share we share the kitchen.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-quadratmeter', 'telc-deutsch-b1', 48, 'der Quadratmeter', 'square metre', 'noun', 'die Quadratmeter', 'Die Wohnung hat etwa siebzig Quadratmeter.', 'The flat has about seventy square metres.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.gemuetlich', 'telc-deutsch-b1', 49, 'gemütlich', 'cosy, comfortable', 'adj', NULL, 'Unser Wohnzimmer ist klein, aber sehr gemütlich.', 'Our living room is small but very cosy.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-arbeitgeber', 'telc-deutsch-b1', 50, 'der Arbeitgeber', 'employer', 'noun', 'die Arbeitgeber', 'Mein Arbeitgeber bezahlt mir die Fahrkarte für den Bus.', 'My employer pays for my bus ticket.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-arbeitnehmer', 'telc-deutsch-b1', 51, 'der Arbeitnehmer', 'employee', 'noun', 'die Arbeitnehmer', 'Die Arbeitnehmer fordern höhere Löhne.', 'The employees are demanding higher wages.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-bewerbung', 'telc-deutsch-b1', 52, 'die Bewerbung', 'application', 'noun', 'die Bewerbungen', 'Ich habe meine Bewerbung gestern per E-Mail geschickt.', 'I sent my application by email yesterday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-bewerbungsgespraech', 'telc-deutsch-b1', 53, 'das Bewerbungsgespräch', 'job interview', 'noun', 'die Bewerbungsgespräche', 'Das Bewerbungsgespräch hat fast eine Stunde gedauert.', 'The job interview lasted almost an hour.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-lebenslauf', 'telc-deutsch-b1', 54, 'der Lebenslauf', 'CV, résumé', 'noun', 'die Lebensläufe', 'Im Lebenslauf müssen alle Stationen genau stehen.', 'All your stations must be listed precisely in your CV.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-stelle', 'telc-deutsch-b1', 55, 'die Stelle', 'position, job', 'noun', 'die Stellen', 'Sie hat eine neue Stelle als Verkäuferin gefunden.', 'She has found a new position as a sales assistant.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-kollege', 'telc-deutsch-b1', 56, 'der Kollege', 'colleague', 'noun', 'die Kollegen', 'Meine Kollegen sind sehr freundlich und hilfsbereit.', 'My colleagues are very friendly and helpful.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kollegin', 'telc-deutsch-b1', 57, 'die Kollegin', 'colleague (female)', 'noun', 'die Kolleginnen', 'Meine Kollegin hilft mir oft bei schwierigen Aufgaben.', 'My colleague often helps me with difficult tasks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-vorgesetzte', 'telc-deutsch-b1', 58, 'der Vorgesetzte', 'superior, boss', 'noun', 'die Vorgesetzten', 'Mein Vorgesetzter ist mit meiner Arbeit sehr zufrieden.', 'My superior is very satisfied with my work.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-erfahrung', 'telc-deutsch-b1', 59, 'die Erfahrung', 'experience', 'noun', 'die Erfahrungen', 'Ich habe drei Jahre Erfahrung im Verkauf gesammelt.', 'I have gathered three years of experience in sales.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-qualifikation', 'telc-deutsch-b1', 60, 'die Qualifikation', 'qualification', 'noun', 'die Qualifikationen', 'Für diese Stelle braucht man eine gute Qualifikation.', 'You need a good qualification for this position.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-karriere', 'telc-deutsch-b1', 61, 'die Karriere', 'career', 'noun', 'die Karrieren', 'Sie hat in kurzer Zeit eine steile Karriere gemacht.', 'She has had a rapid career in a short time.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-gehalt', 'telc-deutsch-b1', 62, 'das Gehalt', 'salary', 'noun', 'die Gehälter', 'Das Gehalt ist gut, aber die Arbeit ist sehr stressig.', 'The salary is good, but the work is very stressful.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-lohn', 'telc-deutsch-b1', 63, 'der Lohn', 'wage', 'noun', 'die Löhne', 'Die Mitarbeiter wollen einen höheren Lohn.', 'The employees want a higher wage.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ueberstunde', 'telc-deutsch-b1', 64, 'die Überstunde', 'overtime hour', 'noun', 'die Überstunden', 'Ich habe diese Woche viele Überstunden gemacht.', 'I worked a lot of overtime this week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kuendigung', 'telc-deutsch-b1', 65, 'die Kündigung', 'notice, termination', 'noun', 'die Kündigungen', 'Nach der Kündigung sucht er sofort eine neue Arbeit.', 'After the termination he is immediately looking for a new job.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.kuendigen', 'telc-deutsch-b1', 66, 'kündigen', 'to give notice, to quit', 'verb', NULL, 'Weil die Firma sparen muss, hat sie zehn Mitarbeiter gekündigt.', 'Because the company has to save money, it has given ten employees notice.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-teilzeit', 'telc-deutsch-b1', 67, 'die Teilzeit', 'part-time work', 'noun', 'die Teilzeiten', 'Nach der Geburt arbeitet sie nur noch in Teilzeit.', 'After the birth she only works part-time.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-besprechung', 'telc-deutsch-b1', 68, 'die Besprechung', 'meeting, discussion', 'noun', 'die Besprechungen', 'Die Besprechung dauert leider länger als geplant.', 'Unfortunately the meeting is taking longer than planned.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-aufgabe', 'telc-deutsch-b1', 69, 'die Aufgabe', 'task, duty', 'noun', 'die Aufgaben', 'Meine Aufgabe ist es, die Kunden gut zu beraten.', 'My task is to advise the customers well.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-kunde', 'telc-deutsch-b1', 70, 'der Kunde', 'customer, client', 'noun', 'die Kunden', 'Der Kunde hat sich über die späte Lieferung beschwert.', 'The customer complained about the late delivery.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-abteilung', 'telc-deutsch-b1', 71, 'die Abteilung', 'department', 'noun', 'die Abteilungen', 'Ich arbeite in der Abteilung für Marketing.', 'I work in the marketing department.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.zustaendig', 'telc-deutsch-b1', 72, 'zuständig', 'responsible (for), in charge', 'adj', NULL, 'Für diese Frage ist meine Kollegin zuständig.', 'My colleague is responsible for this question.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.fleissig', 'telc-deutsch-b1', 73, 'fleißig', 'hard-working, diligent', 'adj', NULL, 'Sie ist sehr fleißig und lernt jeden Abend zwei Stunden.', 'She is very hard-working and studies for two hours every evening.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.arbeitslos', 'telc-deutsch-b1', 74, 'arbeitslos', 'unemployed', 'adj', NULL, 'Nach der Kündigung war er sechs Monate arbeitslos.', 'After being made redundant he was unemployed for six months.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ausbildung', 'telc-deutsch-b1', 75, 'die Ausbildung', 'vocational training, apprenticeship', 'noun', 'die Ausbildungen', 'Nach der Schule macht sie eine Ausbildung als Krankenschwester.', 'After school she is doing training as a nurse.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-studiengang', 'telc-deutsch-b1', 76, 'der Studiengang', 'degree course', 'noun', 'die Studiengänge', 'Mein Studiengang dauert insgesamt sechs Semester.', 'My degree course lasts six semesters in total.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-universitaet', 'telc-deutsch-b1', 77, 'die Universität', 'university', 'noun', 'die Universitäten', 'Sie studiert Medizin an der Universität Heidelberg.', 'She studies medicine at Heidelberg University.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-vorlesung', 'telc-deutsch-b1', 78, 'die Vorlesung', 'lecture', 'noun', 'die Vorlesungen', 'Die Vorlesung beginnt heute schon um acht Uhr.', 'The lecture starts at eight o''clock today.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-seminar', 'telc-deutsch-b1', 79, 'das Seminar', 'seminar', 'noun', 'die Seminare', 'Im Seminar müssen wir nächste Woche ein Referat halten.', 'In the seminar we have to give a presentation next week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-pruefung', 'telc-deutsch-b1', 80, 'die Prüfung', 'exam', 'noun', 'die Prüfungen', 'Ich habe die Prüfung beim ersten Versuch bestanden.', 'I passed the exam on the first attempt.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.bestehen', 'telc-deutsch-b1', 81, 'bestehen', 'to pass (an exam)', 'verb', NULL, 'Nur die Hälfte der Teilnehmer hat die Prüfung bestanden.', 'Only half of the participants passed the exam.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.durchfallen', 'telc-deutsch-b1', 82, 'durchfallen', 'to fail (an exam)', 'verb', NULL, 'Er ist in der Prüfung durchgefallen, weil er kaum gelernt hat.', 'He failed the exam because he hardly studied.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-note', 'telc-deutsch-b1', 83, 'die Note', 'mark, grade', 'noun', 'die Noten', 'Sie hat in Mathematik immer gute Noten.', 'She always gets good marks in maths.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-zeugnis', 'telc-deutsch-b1', 84, 'das Zeugnis', 'certificate, school report', 'noun', 'die Zeugnisse', 'Am Ende des Schuljahres bekommen wir ein Zeugnis.', 'At the end of the school year we get a report.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-hausaufgabe', 'telc-deutsch-b1', 85, 'die Hausaufgabe', 'homework', 'noun', 'die Hausaufgaben', 'Die Hausaufgaben mache ich meistens am Abend.', 'I usually do my homework in the evening.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-unterricht', 'telc-deutsch-b1', 86, 'der Unterricht', 'lessons, classes', 'noun', 'die Unterrichte', 'Der Unterricht fängt pünktlich um neun Uhr an.', 'The lessons start punctually at nine o''clock.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-lehrer', 'telc-deutsch-b1', 87, 'der Lehrer', 'teacher', 'noun', 'die Lehrer', 'Unser Lehrer erklärt die Grammatik sehr geduldig.', 'Our teacher explains the grammar very patiently.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-lehrerin', 'telc-deutsch-b1', 88, 'die Lehrerin', 'teacher (female)', 'noun', 'die Lehrerinnen', 'Die Lehrerin hat uns ein neues Buch empfohlen.', 'The teacher recommended a new book to us.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-kurs', 'telc-deutsch-b1', 89, 'der Kurs', 'course', 'noun', 'die Kurse', 'Ich besuche einen Deutschkurs an der Volkshochschule.', 'I am taking a German course at the adult education centre.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-fach', 'telc-deutsch-b1', 90, 'das Fach', 'subject', 'noun', 'die Fächer', 'Mein Lieblingsfach in der Schule war Geschichte.', 'My favourite subject at school was history.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kenntnis', 'telc-deutsch-b1', 91, 'die Kenntnis', 'knowledge, skill', 'noun', 'die Kenntnisse', 'Meine Kenntnisse in Mathematik sind nicht besonders gut.', 'My knowledge of mathematics is not particularly good.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-wissen', 'telc-deutsch-b1', 92, 'das Wissen', 'knowledge', 'noun', 'das Wissen', 'Sein Wissen über Computer ist wirklich beeindruckend.', 'His knowledge about computers is really impressive.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-studium', 'telc-deutsch-b1', 93, 'das Studium', 'studies, degree', 'noun', 'die Studien', 'Sie hat ihr Studium nach zwei Jahren abgebrochen.', 'She dropped out of her studies after two years.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-abschluss', 'telc-deutsch-b1', 94, 'der Abschluss', 'degree, qualification', 'noun', 'die Abschlüsse', 'Nach dem Abschluss möchte er ein Jahr ins Ausland gehen.', 'After graduating he wants to go abroad for a year.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-nachhilfe', 'telc-deutsch-b1', 95, 'die Nachhilfe', 'private tuition', 'noun', 'die Nachhilfen', 'Mein Sohn bekommt zweimal pro Woche Nachhilfe in Englisch.', 'My son gets English tutoring twice a week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-mitschueler', 'telc-deutsch-b1', 96, 'der Mitschüler', 'classmate', 'noun', 'die Mitschüler', 'Meine Mitschüler und ich lernen zusammen für die Prüfung.', 'My classmates and I study together for the exam.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.ueben', 'telc-deutsch-b1', 97, 'üben', 'to practise', 'verb', NULL, 'Ich muss noch viel üben, bevor ich die Prüfung mache.', 'I still have to practise a lot before I take the exam.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.wiederholen', 'telc-deutsch-b1', 98, 'wiederholen', 'to repeat, to revise', 'verb', NULL, 'Vor der Prüfung wiederhole ich alle Vokabeln noch einmal.', 'Before the exam I revise all the vocabulary once more.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-referat', 'telc-deutsch-b1', 99, 'das Referat', 'presentation, paper', 'noun', 'die Referate', 'Ich halte nächste Woche ein Referat über Umweltschutz.', 'Next week I am giving a presentation about environmental protection.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-geschaeft', 'telc-deutsch-b1', 100, 'das Geschäft', 'shop, business', 'noun', 'die Geschäfte', 'Das Geschäft schließt heute schon um achtzehn Uhr.', 'The shop closes at six o''clock today.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-einkauf', 'telc-deutsch-b1', 101, 'der Einkauf', 'purchase, shopping', 'noun', 'die Einkäufe', 'Der Einkauf im Supermarkt war diesmal ziemlich teuer.', 'The shopping at the supermarket was quite expensive this time.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kasse', 'telc-deutsch-b1', 102, 'die Kasse', 'checkout, cash desk', 'noun', 'die Kassen', 'An der Kasse standen viele Leute mit vollen Körben.', 'Many people with full baskets were standing at the checkout.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-quittung', 'telc-deutsch-b1', 103, 'die Quittung', 'receipt', 'noun', 'die Quittungen', 'Kann ich bitte eine Quittung bekommen?', 'Could I please have a receipt?', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-preis', 'telc-deutsch-b1', 104, 'der Preis', 'price', 'noun', 'die Preise', 'Die Preise für Obst sind in diesem Jahr stark gestiegen.', 'The prices for fruit have risen sharply this year.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-angebot', 'telc-deutsch-b1', 105, 'das Angebot', 'offer, special offer', 'noun', 'die Angebote', 'Diese Woche gibt es Milch und Käse im Angebot.', 'This week milk and cheese are on special offer.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-rabatt', 'telc-deutsch-b1', 106, 'der Rabatt', 'discount', 'noun', 'die Rabatte', 'Auf alle Schuhe gibt es heute zehn Prozent Rabatt.', 'There is a ten percent discount on all shoes today.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-rechnung', 'telc-deutsch-b1', 107, 'die Rechnung', 'bill, invoice', 'noun', 'die Rechnungen', 'Die Rechnung können Sie auch mit Karte bezahlen.', 'You can also pay the bill by card.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.bezahlen', 'telc-deutsch-b1', 108, 'bezahlen', 'to pay', 'verb', NULL, 'Ich möchte bitte mit Karte bezahlen.', 'I would like to pay by card, please.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kreditkarte', 'telc-deutsch-b1', 109, 'die Kreditkarte', 'credit card', 'noun', 'die Kreditkarten', 'Kann ich hier auch mit Kreditkarte zahlen?', 'Can I also pay by credit card here?', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-kleingeld', 'telc-deutsch-b1', 110, 'das Kleingeld', 'small change', 'noun', 'das Kleingeld', 'Hast du Kleingeld für den Automaten?', 'Do you have small change for the machine?', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-verkaeufer', 'telc-deutsch-b1', 111, 'der Verkäufer', 'salesman, shop assistant', 'noun', 'die Verkäufer', 'Der Verkäufer hat mir eine andere Größe gebracht.', 'The shop assistant brought me a different size.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-verkaeuferin', 'telc-deutsch-b1', 112, 'die Verkäuferin', 'saleswoman, shop assistant (female)', 'noun', 'die Verkäuferinnen', 'Die Verkäuferin war sehr freundlich und hat mir alles erklärt.', 'The shop assistant was very friendly and explained everything to me.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ware', 'telc-deutsch-b1', 113, 'die Ware', 'goods, merchandise', 'noun', 'die Waren', 'Die Ware ist leider beschädigt bei uns angekommen.', 'Unfortunately the goods arrived with us damaged.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.umtauschen', 'telc-deutsch-b1', 114, 'umtauschen', 'to exchange', 'verb', NULL, 'Kann ich diese Hose umtauschen, wenn sie nicht passt?', 'Can I exchange these trousers if they don''t fit?', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-groesse', 'telc-deutsch-b1', 115, 'die Größe', 'size', 'noun', 'die Größen', 'Haben Sie das Hemd auch in einer größeren Größe?', 'Do you have the shirt in a larger size as well?', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-qualitaet', 'telc-deutsch-b1', 116, 'die Qualität', 'quality', 'noun', 'die Qualitäten', 'Bei Kleidung achte ich immer auf gute Qualität.', 'When it comes to clothes I always look for good quality.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-verbraucher', 'telc-deutsch-b1', 117, 'der Verbraucher', 'consumer', 'noun', 'die Verbraucher', 'Die Verbraucher beschweren sich über die hohen Preise.', 'Consumers are complaining about the high prices.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.guenstig', 'telc-deutsch-b1', 118, 'günstig', 'cheap, favourable', 'adj', NULL, 'In diesem Laden sind die Preise besonders günstig.', 'In this shop the prices are particularly cheap.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-lieferung', 'telc-deutsch-b1', 119, 'die Lieferung', 'delivery', 'noun', 'die Lieferungen', 'Die Lieferung dauert normalerweise drei bis vier Tage.', 'The delivery usually takes three to four days.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.bestellen', 'telc-deutsch-b1', 120, 'bestellen', 'to order', 'verb', NULL, 'Ich habe das Buch gestern online bestellt.', 'I ordered the book online yesterday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-sonderangebot', 'telc-deutsch-b1', 121, 'das Sonderangebot', 'special offer', 'noun', 'die Sonderangebote', 'Im Sonderangebot kostet das nur fünf Euro.', 'In the special offer it only costs five euros.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-supermarkt', 'telc-deutsch-b1', 122, 'der Supermarkt', 'supermarket', 'noun', 'die Supermärkte', 'Ich gehe zweimal pro Woche in den Supermarkt.', 'I go to the supermarket twice a week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sparen', 'telc-deutsch-b1', 123, 'sparen', 'to save (money)', 'verb', NULL, 'Wir sparen jeden Monat Geld für den Urlaub.', 'We save money every month for our holiday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.ausgeben', 'telc-deutsch-b1', 124, 'ausgeben', 'to spend', 'verb', NULL, 'Ich habe am Wochenende viel Geld ausgegeben.', 'I spent a lot of money at the weekend.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-gesundheit', 'telc-deutsch-b1', 125, 'die Gesundheit', 'health', 'noun', 'die Gesundheit', 'Gesundheit ist wichtiger als Geld.', 'Health is more important than money.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-arzt', 'telc-deutsch-b1', 126, 'der Arzt', 'doctor', 'noun', 'die Ärzte', 'Ich muss morgen früh zum Arzt gehen.', 'I have to go to the doctor tomorrow morning.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-aerztin', 'telc-deutsch-b1', 127, 'die Ärztin', 'doctor (female)', 'noun', 'die Ärztinnen', 'Die Ärztin hat mir ein Rezept ausgestellt.', 'The doctor wrote me a prescription.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-praxis', 'telc-deutsch-b1', 128, 'die Praxis', 'doctor''s practice, surgery', 'noun', 'die Praxen', 'Die Praxis ist am Mittwochnachmittag geschlossen.', 'The practice is closed on Wednesday afternoon.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-krankheit', 'telc-deutsch-b1', 129, 'die Krankheit', 'illness, disease', 'noun', 'die Krankheiten', 'Nach einer langen Krankheit ist er endlich wieder gesund.', 'After a long illness he is finally healthy again.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.krank', 'telc-deutsch-b1', 130, 'krank', 'ill, sick', 'adj', NULL, 'Ich war letzte Woche drei Tage krank.', 'I was ill for three days last week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-erkaeltung', 'telc-deutsch-b1', 131, 'die Erkältung', 'cold (illness)', 'noun', 'die Erkältungen', 'Im Winter habe ich oft eine starke Erkältung.', 'In winter I often have a bad cold.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-fieber', 'telc-deutsch-b1', 132, 'das Fieber', 'fever', 'noun', 'das Fieber', 'Das Kind hat hohes Fieber und muss im Bett bleiben.', 'The child has a high fever and has to stay in bed.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-husten', 'telc-deutsch-b1', 133, 'der Husten', 'cough', 'noun', 'der Husten', 'Mein Husten wird einfach nicht besser.', 'My cough just won''t get better.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-schmerzen', 'telc-deutsch-b1', 134, 'die Schmerzen', 'pain, aches', 'noun', 'die Schmerzen', 'Ich habe seit gestern starke Schmerzen im Rücken.', 'I have had severe pain in my back since yesterday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-tablette', 'telc-deutsch-b1', 135, 'die Tablette', 'tablet, pill', 'noun', 'die Tabletten', 'Nehmen Sie die Tabletten dreimal täglich nach dem Essen.', 'Take the tablets three times a day after meals.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-medikament', 'telc-deutsch-b1', 136, 'das Medikament', 'medicine, medication', 'noun', 'die Medikamente', 'Dieses Medikament darf man nicht mit Alkohol nehmen.', 'You must not take this medication with alcohol.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-rezept', 'telc-deutsch-b1', 137, 'das Rezept', 'prescription, recipe', 'noun', 'die Rezepte', 'Ohne Rezept bekommt man dieses Medikament nicht.', 'You cannot get this medication without a prescription.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-apotheke', 'telc-deutsch-b1', 138, 'die Apotheke', 'pharmacy, chemist''s', 'noun', 'die Apotheken', 'Die Apotheke hat auch am Samstag geöffnet.', 'The pharmacy is also open on Saturdays.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-versicherung', 'telc-deutsch-b1', 139, 'die Versicherung', 'insurance', 'noun', 'die Versicherungen', 'Meine Versicherung bezahlt zum Glück die ganze Behandlung.', 'Luckily my insurance pays for the whole treatment.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sich-verletzen', 'telc-deutsch-b1', 140, 'sich verletzen', 'to injure oneself', 'verb', NULL, 'Beim Fußballspielen hat er sich am Knie verletzt.', 'He injured his knee playing football.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-verletzung', 'telc-deutsch-b1', 141, 'die Verletzung', 'injury', 'noun', 'die Verletzungen', 'Die Verletzung ist zum Glück nicht so schlimm.', 'Fortunately the injury is not that bad.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sich-erholen', 'telc-deutsch-b1', 142, 'sich erholen', 'to recover, to rest', 'verb', NULL, 'Im Urlaub konnte ich mich endlich richtig erholen.', 'On holiday I was finally able to really recover.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-behandlung', 'telc-deutsch-b1', 143, 'die Behandlung', 'treatment', 'noun', 'die Behandlungen', 'Die Behandlung dauert etwa drei Wochen.', 'The treatment takes about three weeks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ernaehrung', 'telc-deutsch-b1', 144, 'die Ernährung', 'nutrition, diet', 'noun', 'die Ernährungen', 'Eine ausgewogene Ernährung hilft gegen viele Krankheiten.', 'A balanced diet helps against many illnesses.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-bewegung', 'telc-deutsch-b1', 145, 'die Bewegung', 'exercise, movement', 'noun', 'die Bewegungen', 'Jeden Tag etwas Bewegung tut dem Körper sehr gut.', 'A bit of exercise every day is very good for the body.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-gewicht', 'telc-deutsch-b1', 146, 'das Gewicht', 'weight', 'noun', 'die Gewichte', 'In den Ferien habe ich zwei Kilo an Gewicht zugenommen.', 'During the holidays I put on two kilos in weight.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.abnehmen', 'telc-deutsch-b1', 147, 'abnehmen', 'to lose weight', 'verb', NULL, 'Sie möchte bis zum Sommer fünf Kilo abnehmen.', 'She wants to lose five kilos by the summer.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-magen', 'telc-deutsch-b1', 148, 'der Magen', 'stomach', 'noun', 'die Mägen', 'Auf nüchternen Magen sollte man keine Tabletten nehmen.', 'You should not take tablets on an empty stomach.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-krankenhaus', 'telc-deutsch-b1', 149, 'das Krankenhaus', 'hospital', 'noun', 'die Krankenhäuser', 'Nach dem Unfall lag er zwei Wochen im Krankenhaus.', 'After the accident he was in hospital for two weeks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-reise', 'telc-deutsch-b1', 150, 'die Reise', 'journey, trip', 'noun', 'die Reisen', 'Die Reise nach Italien hat zwei Wochen gedauert.', 'The trip to Italy lasted two weeks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-fahrkarte', 'telc-deutsch-b1', 151, 'die Fahrkarte', 'ticket (for public transport)', 'noun', 'die Fahrkarten', 'Ich habe die Fahrkarte schon online gekauft.', 'I already bought the ticket online.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-bahnhof', 'telc-deutsch-b1', 152, 'der Bahnhof', 'train station', 'noun', 'die Bahnhöfe', 'Wir treffen uns um neun Uhr am Bahnhof.', 'We are meeting at the station at nine o''clock.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-flughafen', 'telc-deutsch-b1', 153, 'der Flughafen', 'airport', 'noun', 'die Flughäfen', 'Der Flughafen liegt eine Stunde von der Stadt entfernt.', 'The airport is an hour away from the city.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-gleis', 'telc-deutsch-b1', 154, 'das Gleis', 'platform, track', 'noun', 'die Gleise', 'Der Zug nach München fährt von Gleis acht ab.', 'The train to Munich departs from platform eight.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-abflug', 'telc-deutsch-b1', 155, 'der Abflug', 'departure (flight)', 'noun', 'die Abflüge', 'Der Abflug wurde wegen des Sturms verschoben.', 'The departure was postponed because of the storm.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ankunft', 'telc-deutsch-b1', 156, 'die Ankunft', 'arrival', 'noun', 'die Ankünfte', 'Nach unserer Ankunft sind wir sofort ins Hotel gefahren.', 'After our arrival we went straight to the hotel.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-verspaetung', 'telc-deutsch-b1', 157, 'die Verspätung', 'delay', 'noun', 'die Verspätungen', 'Der Zug hat wieder zwanzig Minuten Verspätung.', 'The train is twenty minutes late again.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.umsteigen', 'telc-deutsch-b1', 158, 'umsteigen', 'to change (trains, buses)', 'verb', NULL, 'In Frankfurt müssen wir in einen anderen Zug umsteigen.', 'In Frankfurt we have to change to another train.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-unterkunft', 'telc-deutsch-b1', 159, 'die Unterkunft', 'accommodation', 'noun', 'die Unterkünfte', 'Die Unterkunft war einfach, aber sehr sauber.', 'The accommodation was simple but very clean.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-jugendherberge', 'telc-deutsch-b1', 160, 'die Jugendherberge', 'youth hostel', 'noun', 'die Jugendherbergen', 'Wir haben drei Nächte in einer Jugendherberge geschlafen.', 'We slept in a youth hostel for three nights.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-buchung', 'telc-deutsch-b1', 161, 'die Buchung', 'booking, reservation', 'noun', 'die Buchungen', 'Die Buchung des Hotels hat problemlos geklappt.', 'The booking of the hotel went without any problems.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.buchen', 'telc-deutsch-b1', 162, 'buchen', 'to book', 'verb', NULL, 'Wir haben den Flug schon im Januar gebucht.', 'We already booked the flight in January.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-gepaeck', 'telc-deutsch-b1', 163, 'das Gepäck', 'luggage', 'noun', 'das Gepäck', 'Mein Gepäck ist leider nicht in Berlin angekommen.', 'Unfortunately my luggage did not arrive in Berlin.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-koffer', 'telc-deutsch-b1', 164, 'der Koffer', 'suitcase', 'noun', 'die Koffer', 'Ich habe viel zu viel in den Koffer gepackt.', 'I packed far too much into the suitcase.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-grenze', 'telc-deutsch-b1', 165, 'die Grenze', 'border', 'noun', 'die Grenzen', 'An der Grenze mussten wir unsere Pässe zeigen.', 'At the border we had to show our passports.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-verkehr', 'telc-deutsch-b1', 166, 'der Verkehr', 'traffic', 'noun', 'der Verkehr', 'Am Morgen ist der Verkehr in der Stadt besonders stark.', 'In the morning the traffic in the city is particularly heavy.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-sehenswuerdigkeit', 'telc-deutsch-b1', 167, 'die Sehenswürdigkeit', 'sight, tourist attraction', 'noun', 'die Sehenswürdigkeiten', 'In Berlin gibt es sehr viele Sehenswürdigkeiten.', 'There are a great many sights in Berlin.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.besichtigen', 'telc-deutsch-b1', 168, 'besichtigen', 'to visit, to view', 'verb', NULL, 'Am Nachmittag wollen wir das Schloss besichtigen.', 'In the afternoon we want to visit the castle.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-aufenthalt', 'telc-deutsch-b1', 169, 'der Aufenthalt', 'stay, sojourn', 'noun', 'die Aufenthalte', 'Unser Aufenthalt in Wien war leider viel zu kurz.', 'Unfortunately our stay in Vienna was far too short.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-ausland', 'telc-deutsch-b1', 170, 'das Ausland', 'abroad, foreign countries', 'noun', 'das Ausland', 'Sie arbeitet seit zwei Jahren im Ausland.', 'She has been working abroad for two years.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-autobahn', 'telc-deutsch-b1', 171, 'die Autobahn', 'motorway', 'noun', 'die Autobahnen', 'Auf der Autobahn gab es einen langen Stau.', 'There was a long traffic jam on the motorway.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-stau', 'telc-deutsch-b1', 172, 'der Stau', 'traffic jam', 'noun', 'die Staus', 'Wir standen zwei Stunden im Stau.', 'We were stuck in a traffic jam for two hours.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kreuzung', 'telc-deutsch-b1', 173, 'die Kreuzung', 'crossroads, junction', 'noun', 'die Kreuzungen', 'An der nächsten Kreuzung müssen Sie links abbiegen.', 'At the next junction you have to turn left.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-fuehrerschein', 'telc-deutsch-b1', 174, 'der Führerschein', 'driving licence', 'noun', 'die Führerscheine', 'Mit achtzehn habe ich endlich meinen Führerschein gemacht.', 'At eighteen I finally got my driving licence.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-freizeit', 'telc-deutsch-b1', 175, 'die Freizeit', 'free time, leisure', 'noun', 'die Freizeiten', 'In meiner Freizeit spiele ich Tennis und lese viel.', 'In my free time I play tennis and read a lot.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-hobby', 'telc-deutsch-b1', 176, 'das Hobby', 'hobby', 'noun', 'die Hobbys', 'Mein größtes Hobby ist das Fotografieren.', 'My biggest hobby is photography.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-veranstaltung', 'telc-deutsch-b1', 177, 'die Veranstaltung', 'event', 'noun', 'die Veranstaltungen', 'Die Veranstaltung findet bei jedem Wetter statt.', 'The event takes place whatever the weather.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-eintrittskarte', 'telc-deutsch-b1', 178, 'die Eintrittskarte', 'admission ticket', 'noun', 'die Eintrittskarten', 'Die Eintrittskarten für das Konzert waren schnell ausverkauft.', 'The admission tickets for the concert sold out quickly.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-ausstellung', 'telc-deutsch-b1', 179, 'die Ausstellung', 'exhibition', 'noun', 'die Ausstellungen', 'Wir haben uns eine Ausstellung über moderne Kunst angesehen.', 'We looked at an exhibition about modern art.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-konzert', 'telc-deutsch-b1', 180, 'das Konzert', 'concert', 'noun', 'die Konzerte', 'Das Konzert hat erst um einundzwanzig Uhr angefangen.', 'The concert only started at nine in the evening.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-film', 'telc-deutsch-b1', 181, 'der Film', 'film, movie', 'noun', 'die Filme', 'Der Film war spannend, aber ziemlich lang.', 'The film was exciting but quite long.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-sendung', 'telc-deutsch-b1', 182, 'die Sendung', 'programme, broadcast', 'noun', 'die Sendungen', 'Diese Sendung läuft jeden Sonntagabend.', 'This programme is on every Sunday evening.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-nachrichten', 'telc-deutsch-b1', 183, 'die Nachrichten', 'the news', 'noun', 'die Nachrichten', 'Ich höre die Nachrichten jeden Morgen im Radio.', 'I listen to the news on the radio every morning.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-zeitschrift', 'telc-deutsch-b1', 184, 'die Zeitschrift', 'magazine, journal', 'noun', 'die Zeitschriften', 'Sie liest gern Zeitschriften über Mode und Reisen.', 'She likes reading magazines about fashion and travel.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-zeitung', 'telc-deutsch-b1', 185, 'die Zeitung', 'newspaper', 'noun', 'die Zeitungen', 'Mein Vater liest die Zeitung immer beim Frühstück.', 'My father always reads the newspaper at breakfast.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-fernseher', 'telc-deutsch-b1', 186, 'der Fernseher', 'television set', 'noun', 'die Fernseher', 'Unser Fernseher ist leider schon wieder kaputt.', 'Unfortunately our television set is broken again.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-internet', 'telc-deutsch-b1', 187, 'das Internet', 'internet', 'noun', 'das Internet', 'Im Internet finde ich schnell die Informationen, die ich brauche.', 'On the internet I quickly find the information I need.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-werbung', 'telc-deutsch-b1', 188, 'die Werbung', 'advertising, advertisement', 'noun', 'die Werbungen', 'Die Werbung vor dem Film dauert fast zehn Minuten.', 'The advertising before the film lasts almost ten minutes.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-programm', 'telc-deutsch-b1', 189, 'das Programm', 'programme', 'noun', 'die Programme', 'Heute Abend kommt ein interessantes Programm im Fernsehen.', 'There is an interesting programme on television tonight.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-zuschauer', 'telc-deutsch-b1', 190, 'der Zuschauer', 'viewer, spectator', 'noun', 'die Zuschauer', 'Millionen Zuschauer haben das Finale gesehen.', 'Millions of viewers watched the final.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-band', 'telc-deutsch-b1', 191, 'die Band', 'band', 'noun', 'die Bands', 'Die Band spielt am Samstag in einem kleinen Club.', 'The band is playing in a small club on Saturday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-verein', 'telc-deutsch-b1', 192, 'der Verein', 'club, association', 'noun', 'die Vereine', 'In unserem Verein spielen wir einmal pro Woche Fußball.', 'In our club we play football once a week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-mitglied', 'telc-deutsch-b1', 193, 'das Mitglied', 'member', 'noun', 'die Mitglieder', 'Unser Verein hat über hundert Mitglieder.', 'Our club has more than a hundred members.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.wandern', 'telc-deutsch-b1', 194, 'wandern', 'to hike, to go walking', 'verb', NULL, 'Am Wochenende wandern wir gern in den Bergen.', 'At the weekend we like hiking in the mountains.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-mannschaft', 'telc-deutsch-b1', 195, 'die Mannschaft', 'team', 'noun', 'die Mannschaften', 'Unsere Mannschaft hat das Spiel zwei zu eins gewonnen.', 'Our team won the match two to one.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.gewinnen', 'telc-deutsch-b1', 196, 'gewinnen', 'to win', 'verb', NULL, 'Wenn wir das nächste Spiel gewinnen, sind wir Meister.', 'If we win the next match, we will be champions.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.verlieren', 'telc-deutsch-b1', 197, 'verlieren', 'to lose', 'verb', NULL, 'Leider haben wir das Finale knapp verloren.', 'Unfortunately we narrowly lost the final.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sich-interessieren', 'telc-deutsch-b1', 198, 'sich interessieren', 'to be interested (in)', 'verb', NULL, 'Ich interessiere mich sehr für Geschichte und Politik.', 'I am very interested in history and politics.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-roman', 'telc-deutsch-b1', 199, 'der Roman', 'novel', 'noun', 'die Romane', 'Sie liest gerade einen spannenden Roman.', 'She is currently reading an exciting novel.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-amt', 'telc-deutsch-b1', 200, 'das Amt', 'office, public authority', 'noun', 'die Ämter', 'Für den neuen Pass muss ich zum Amt gehen.', 'I have to go to the office for the new passport.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-behoerde', 'telc-deutsch-b1', 201, 'die Behörde', 'authority, government agency', 'noun', 'die Behörden', 'Die Behörde hat meinen Antrag noch nicht bearbeitet.', 'The authority has not yet processed my application.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-antrag', 'telc-deutsch-b1', 202, 'der Antrag', 'application, request', 'noun', 'die Anträge', 'Ich habe einen Antrag auf Arbeitslosengeld gestellt.', 'I submitted an application for unemployment benefit.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.beantragen', 'telc-deutsch-b1', 203, 'beantragen', 'to apply for', 'verb', NULL, 'Sie hat eine neue Aufenthaltserlaubnis beantragt.', 'She applied for a new residence permit.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-formular', 'telc-deutsch-b1', 204, 'das Formular', 'form', 'noun', 'die Formulare', 'Bitte füllen Sie das Formular vollständig aus.', 'Please fill in the form completely.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.ausfuellen', 'telc-deutsch-b1', 205, 'ausfüllen', 'to fill in', 'verb', NULL, 'Ich muss heute noch das Formular für die Krankenkasse ausfüllen.', 'I still have to fill in the form for the health insurance today.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-unterschrift', 'telc-deutsch-b1', 206, 'die Unterschrift', 'signature', 'noun', 'die Unterschriften', 'Ohne Unterschrift ist der Antrag leider nicht gültig.', 'Without a signature the application is unfortunately not valid.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.unterschreiben', 'telc-deutsch-b1', 207, 'unterschreiben', 'to sign', 'verb', NULL, 'Hier müssen Sie den Vertrag unterschreiben.', 'You have to sign the contract here.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-ausweis', 'telc-deutsch-b1', 208, 'der Ausweis', 'identity card, ID', 'noun', 'die Ausweise', 'Bitte zeigen Sie Ihren Ausweis an der Rezeption.', 'Please show your ID at the reception desk.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-anmeldung', 'telc-deutsch-b1', 209, 'die Anmeldung', 'registration', 'noun', 'die Anmeldungen', 'Die Anmeldung beim Einwohnermeldeamt ist in Deutschland Pflicht.', 'Registration at the residents'' registration office is compulsory in Germany.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-aufenthaltserlaubnis', 'telc-deutsch-b1', 210, 'die Aufenthaltserlaubnis', 'residence permit', 'noun', 'die Aufenthaltserlaubnisse', 'Meine Aufenthaltserlaubnis muss ich im Juni verlängern lassen.', 'I have to have my residence permit extended in June.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-staatsangehoerigkeit', 'telc-deutsch-b1', 211, 'die Staatsangehörigkeit', 'nationality, citizenship', 'noun', 'die Staatsangehörigkeiten', 'Im Formular steht die Frage nach der Staatsangehörigkeit.', 'The form asks about your nationality.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-bescheinigung', 'telc-deutsch-b1', 212, 'die Bescheinigung', 'certificate, written confirmation', 'noun', 'die Bescheinigungen', 'Die Krankenkasse schickt mir eine Bescheinigung für den Arbeitgeber.', 'The health insurance is sending me a certificate for my employer.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-frist', 'telc-deutsch-b1', 213, 'die Frist', 'deadline, time limit', 'noun', 'die Fristen', 'Die Frist für den Antrag läuft am Freitag ab.', 'The deadline for the application expires on Friday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-gebuehr', 'telc-deutsch-b1', 214, 'die Gebühr', 'fee, charge', 'noun', 'die Gebühren', 'Für den neuen Pass muss man eine Gebühr bezahlen.', 'You have to pay a fee for the new passport.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.gueltig', 'telc-deutsch-b1', 215, 'gültig', 'valid', 'adj', NULL, 'Mein Pass ist noch zwei Jahre gültig.', 'My passport is still valid for two years.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-genehmigung', 'telc-deutsch-b1', 216, 'die Genehmigung', 'permission, approval', 'noun', 'die Genehmigungen', 'Ohne Genehmigung darf man hier nicht bauen.', 'You are not allowed to build here without permission.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-vertrag', 'telc-deutsch-b1', 217, 'der Vertrag', 'contract', 'noun', 'die Verträge', 'Ich habe den Vertrag genau gelesen, bevor ich unterschrieben habe.', 'I read the contract carefully before I signed it.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-steuer', 'telc-deutsch-b1', 218, 'die Steuer', 'tax', 'noun', 'die Steuern', 'Von meinem Gehalt werden jeden Monat Steuern abgezogen.', 'Taxes are deducted from my salary every month.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-einkommen', 'telc-deutsch-b1', 219, 'das Einkommen', 'income', 'noun', 'die Einkommen', 'Sein Einkommen reicht kaum für die hohe Miete.', 'His income is barely enough for the high rent.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-rente', 'telc-deutsch-b1', 220, 'die Rente', 'pension', 'noun', 'die Renten', 'Seine Rente ist leider sehr niedrig.', 'Unfortunately his pension is very low.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-krankenkasse', 'telc-deutsch-b1', 221, 'die Krankenkasse', 'health insurance fund', 'noun', 'die Krankenkassen', 'Bei der Krankenkasse muss ich meine neue Adresse melden.', 'I have to report my new address to the health insurance fund.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.persoenlich', 'telc-deutsch-b1', 222, 'persönlich', 'personal, in person', 'adj', NULL, 'Sie müssen den Antrag persönlich beim Amt abgeben.', 'You have to hand in the application at the office in person.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-bearbeitung', 'telc-deutsch-b1', 223, 'die Bearbeitung', 'processing', 'noun', 'die Bearbeitungen', 'Die Bearbeitung des Antrags dauert etwa vier Wochen.', 'The processing of the application takes about four weeks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-entscheidung', 'telc-deutsch-b1', 224, 'die Entscheidung', 'decision', 'noun', 'die Entscheidungen', 'Die Behörde trifft ihre Entscheidung innerhalb von vier Wochen.', 'The authority makes its decision within four weeks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-umwelt', 'telc-deutsch-b1', 225, 'die Umwelt', 'environment', 'noun', 'die Umwelten', 'Wir müssen die Umwelt besser schützen.', 'We have to protect the environment better.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-umweltschutz', 'telc-deutsch-b1', 226, 'der Umweltschutz', 'environmental protection', 'noun', 'der Umweltschutz', 'Umweltschutz beginnt schon beim täglichen Einkaufen.', 'Environmental protection starts with everyday shopping.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-muell', 'telc-deutsch-b1', 227, 'der Müll', 'rubbish, waste', 'noun', 'der Müll', 'Der Müll wird bei uns jeden Dienstag abgeholt.', 'The rubbish is collected at our place every Tuesday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-muelltrennung', 'telc-deutsch-b1', 228, 'die Mülltrennung', 'waste separation', 'noun', 'die Mülltrennungen', 'In Deutschland ist die Mülltrennung gesetzlich geregelt.', 'In Germany waste separation is regulated by law.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.recyceln', 'telc-deutsch-b1', 229, 'recyceln', 'to recycle', 'verb', NULL, 'Plastikflaschen kann man heutzutage gut recyceln.', 'Nowadays plastic bottles can be recycled well.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-strom', 'telc-deutsch-b1', 230, 'der Strom', 'electricity, power', 'noun', 'der Strom', 'Der Strom aus Windkraft ist umweltfreundlich.', 'Electricity from wind power is environmentally friendly.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-energie', 'telc-deutsch-b1', 231, 'die Energie', 'energy', 'noun', 'die Energien', 'Wir sollten insgesamt weniger Energie verbrauchen.', 'We should consume less energy overall.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-zukunft', 'telc-deutsch-b1', 232, 'die Zukunft', 'future', 'noun', 'die Zukünfte', 'In der Zukunft werden wir vielleicht alle elektrisch fahren.', 'In the future perhaps we will all drive electric cars.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-klima', 'telc-deutsch-b1', 233, 'das Klima', 'climate', 'noun', 'die Klimas', 'Das Klima auf der Erde verändert sich immer schneller.', 'The climate on earth is changing faster and faster.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-klimawandel', 'telc-deutsch-b1', 234, 'der Klimawandel', 'climate change', 'noun', 'der Klimawandel', 'Der Klimawandel ist eine der größten Aufgaben unserer Zeit.', 'Climate change is one of the greatest challenges of our time.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-verschmutzung', 'telc-deutsch-b1', 235, 'die Verschmutzung', 'pollution', 'noun', 'die Verschmutzungen', 'Die Verschmutzung der Flüsse ist ein großes Problem.', 'The pollution of the rivers is a big problem.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.schuetzen', 'telc-deutsch-b1', 236, 'schützen', 'to protect', 'verb', NULL, 'Wir müssen die Wälder vor dem Abholzen schützen.', 'We have to protect the forests from being cleared.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-gesellschaft', 'telc-deutsch-b1', 237, 'die Gesellschaft', 'society', 'noun', 'die Gesellschaften', 'Junge Menschen verändern unsere Gesellschaft.', 'Young people are changing our society.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-bevoelkerung', 'telc-deutsch-b1', 238, 'die Bevölkerung', 'population', 'noun', 'die Bevölkerungen', 'Die Bevölkerung der Stadt wächst jedes Jahr.', 'The population of the city grows every year.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-armut', 'telc-deutsch-b1', 239, 'die Armut', 'poverty', 'noun', 'die Armut', 'Viele Familien leben trotz Arbeit in Armut.', 'Many families live in poverty despite working.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sozial', 'telc-deutsch-b1', 240, 'sozial', 'social', 'adj', NULL, 'Die Regierung plant soziale Reformen für Familien.', 'The government is planning social reforms for families.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-gleichberechtigung', 'telc-deutsch-b1', 241, 'die Gleichberechtigung', 'equal rights, equality', 'noun', 'die Gleichberechtigungen', 'Die Gleichberechtigung von Mann und Frau ist noch nicht überall erreicht.', 'Equal rights for men and women have not yet been achieved everywhere.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-integration', 'telc-deutsch-b1', 242, 'die Integration', 'integration', 'noun', 'die Integrationen', 'Die Integration von Zuwanderern braucht Zeit und Geduld.', 'The integration of immigrants takes time and patience.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-regel', 'telc-deutsch-b1', 243, 'die Regel', 'rule', 'noun', 'die Regeln', 'In der Bibliothek gelten besondere Regeln.', 'Special rules apply in the library.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-gesetz', 'telc-deutsch-b1', 244, 'das Gesetz', 'law', 'noun', 'die Gesetze', 'Das neue Gesetz tritt im Januar in Kraft.', 'The new law comes into force in January.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.verboten', 'telc-deutsch-b1', 245, 'verboten', 'forbidden, prohibited', 'adj', NULL, 'Rauchen ist in diesem Gebäude streng verboten.', 'Smoking is strictly forbidden in this building.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.erlauben', 'telc-deutsch-b1', 246, 'erlauben', 'to allow, to permit', 'verb', NULL, 'Hier ist es nicht erlaubt, Fahrrad zu fahren.', 'It is not allowed to ride a bicycle here.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-pflicht', 'telc-deutsch-b1', 247, 'die Pflicht', 'duty, obligation', 'noun', 'die Pflichten', 'Jeder Bürger hat die Pflicht, Steuern zu zahlen.', 'Every citizen has the duty to pay taxes.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-spende', 'telc-deutsch-b1', 248, 'die Spende', 'donation', 'noun', 'die Spenden', 'Viele Menschen machen Spenden für arme Kinder.', 'Many people make donations for poor children.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.ehrenamtlich', 'telc-deutsch-b1', 249, 'ehrenamtlich', 'voluntary, unpaid', 'adj', NULL, 'Sie arbeitet ehrenamtlich in einem Tierheim.', 'She works voluntarily at an animal shelter.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-gefuehl', 'telc-deutsch-b1', 250, 'das Gefühl', 'feeling', 'noun', 'die Gefühle', 'Ich habe das Gefühl, dass er mich nicht richtig versteht.', 'I have the feeling that he doesn''t really understand me.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-stimmung', 'telc-deutsch-b1', 251, 'die Stimmung', 'mood, atmosphere', 'noun', 'die Stimmungen', 'Die Stimmung auf der Party war sehr gut.', 'The atmosphere at the party was very good.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-freude', 'telc-deutsch-b1', 252, 'die Freude', 'joy, pleasure', 'noun', 'die Freuden', 'Die Kinder hatten große Freude am Schnee.', 'The children took great pleasure in the snow.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.stolz', 'telc-deutsch-b1', 253, 'stolz', 'proud', 'adj', NULL, 'Meine Eltern sind sehr stolz auf mich.', 'My parents are very proud of me.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.eifersuechtig', 'telc-deutsch-b1', 254, 'eifersüchtig', 'jealous', 'adj', NULL, 'Er ist schnell eifersüchtig, wenn sie mit anderen Männern spricht.', 'He quickly gets jealous when she talks to other men.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.nervoes', 'telc-deutsch-b1', 255, 'nervös', 'nervous', 'adj', NULL, 'Vor der Prüfung bin ich immer sehr nervös.', 'I am always very nervous before the exam.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.enttaeuscht', 'telc-deutsch-b1', 256, 'enttäuscht', 'disappointed', 'adj', NULL, 'Ich war ziemlich enttäuscht von dem Film.', 'I was quite disappointed by the film.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.zufrieden', 'telc-deutsch-b1', 257, 'zufrieden', 'satisfied, content', 'adj', NULL, 'Mit meinem neuen Job bin ich sehr zufrieden.', 'I am very satisfied with my new job.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-angst', 'telc-deutsch-b1', 258, 'die Angst', 'fear, anxiety', 'noun', 'die Ängste', 'Viele Menschen haben Angst vor der Zukunft.', 'Many people are afraid of the future.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sich-aergern', 'telc-deutsch-b1', 259, 'sich ärgern', 'to get annoyed, to be angry', 'verb', NULL, 'Ich ärgere mich über den Lärm in der Nacht.', 'I get annoyed about the noise at night.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-aerger', 'telc-deutsch-b1', 260, 'der Ärger', 'trouble, annoyance', 'noun', 'der Ärger', 'Mit dem Nachbarn hatten wir viel Ärger.', 'We had a lot of trouble with the neighbour.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-wut', 'telc-deutsch-b1', 261, 'die Wut', 'anger, rage', 'noun', 'die Wut', 'Seine Wut war zum Glück schnell wieder vorbei.', 'Luckily his anger quickly passed.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.traurig', 'telc-deutsch-b1', 262, 'traurig', 'sad', 'adj', NULL, 'Sie war sehr traurig, als ihr Hund gestorben ist.', 'She was very sad when her dog died.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-meinung', 'telc-deutsch-b1', 263, 'die Meinung', 'opinion', 'noun', 'die Meinungen', 'Meiner Meinung nach ist das keine gute Idee.', 'In my opinion that is not a good idea.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-eindruck', 'telc-deutsch-b1', 264, 'der Eindruck', 'impression', 'noun', 'die Eindrücke', 'Der erste Eindruck von der Stadt war sehr positiv.', 'The first impression of the city was very positive.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.zweifeln', 'telc-deutsch-b1', 265, 'zweifeln', 'to doubt', 'verb', NULL, 'Ich zweifle daran, dass er die Wahrheit sagt.', 'I doubt that he is telling the truth.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.hoffen', 'telc-deutsch-b1', 266, 'hoffen', 'to hope', 'verb', NULL, 'Wir hoffen, dass das Wetter am Wochenende besser wird.', 'We hope that the weather will be better at the weekend.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-hoffnung', 'telc-deutsch-b1', 267, 'die Hoffnung', 'hope', 'noun', 'die Hoffnungen', 'Die Hoffnung auf eine schnelle Lösung habe ich aufgegeben.', 'I have given up hope of a quick solution.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.sich-freuen', 'telc-deutsch-b1', 268, 'sich freuen', 'to be glad, to look forward', 'verb', NULL, 'Ich freue mich schon sehr auf den Urlaub.', 'I am already very much looking forward to the holiday.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.ueberzeugen', 'telc-deutsch-b1', 269, 'überzeugen', 'to convince', 'verb', NULL, 'Seine Argumente haben mich am Ende überzeugt.', 'In the end his arguments convinced me.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-kritik', 'telc-deutsch-b1', 270, 'die Kritik', 'criticism', 'noun', 'die Kritiken', 'Er nimmt jede Kritik sehr persönlich.', 'He takes every criticism very personally.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-vorschlag', 'telc-deutsch-b1', 271, 'der Vorschlag', 'suggestion, proposal', 'noun', 'die Vorschläge', 'Dein Vorschlag gefällt mir sehr gut.', 'I like your suggestion very much.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.vorschlagen', 'telc-deutsch-b1', 272, 'vorschlagen', 'to suggest, to propose', 'verb', NULL, 'Er hat vorgeschlagen, das Treffen zu verschieben.', 'He suggested postponing the meeting.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-sorge', 'telc-deutsch-b1', 273, 'die Sorge', 'worry, concern', 'noun', 'die Sorgen', 'Um meine Gesundheit mache ich mir keine Sorgen.', 'I am not worried about my health.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-verstaendnis', 'telc-deutsch-b1', 274, 'das Verständnis', 'understanding', 'noun', 'das Verständnis', 'Für meine Probleme hat er viel Verständnis.', 'He has a lot of understanding for my problems.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-termin', 'telc-deutsch-b1', 275, 'der Termin', 'appointment', 'noun', 'die Termine', 'Ich habe morgen um zehn Uhr einen Termin beim Zahnarzt.', 'I have a dentist''s appointment tomorrow at ten o''clock.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-verabredung', 'telc-deutsch-b1', 276, 'die Verabredung', 'arrangement, date', 'noun', 'die Verabredungen', 'Wir haben eine Verabredung für Samstagabend.', 'We have an arrangement for Saturday evening.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.puenktlich', 'telc-deutsch-b1', 277, 'pünktlich', 'punctual, on time', 'adj', NULL, 'Der Zug ist heute endlich pünktlich angekommen.', 'The train finally arrived on time today.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-uhrzeit', 'telc-deutsch-b1', 278, 'die Uhrzeit', 'time (of day)', 'noun', 'die Uhrzeiten', 'Kannst du mir die genaue Uhrzeit sagen?', 'Can you tell me the exact time?', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-zeitpunkt', 'telc-deutsch-b1', 279, 'der Zeitpunkt', 'point in time, moment', 'noun', 'die Zeitpunkte', 'Der Zeitpunkt für unser Gespräch passt mir gut.', 'The timing of our conversation suits me well.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.dauern', 'telc-deutsch-b1', 280, 'dauern', 'to last, to take (time)', 'verb', NULL, 'Die Fahrt mit dem Bus dauert etwa eine Stunde.', 'The bus journey takes about an hour.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-dauer', 'telc-deutsch-b1', 281, 'die Dauer', 'duration, length', 'noun', 'die Dauern', 'Die Dauer des Kurses beträgt zwölf Wochen.', 'The duration of the course is twelve weeks.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-zeitraum', 'telc-deutsch-b1', 282, 'der Zeitraum', 'period, time span', 'noun', 'die Zeiträume', 'In diesem Zeitraum habe ich Urlaub.', 'I am on holiday during this period.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.verschieben', 'telc-deutsch-b1', 283, 'verschieben', 'to postpone, to move', 'verb', NULL, 'Wir müssen das Treffen leider verschieben.', 'Unfortunately we have to postpone the meeting.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.absagen', 'telc-deutsch-b1', 284, 'absagen', 'to cancel, to call off', 'verb', NULL, 'Sie hat den Termin kurzfristig abgesagt.', 'She cancelled the appointment at short notice.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.vereinbaren', 'telc-deutsch-b1', 285, 'vereinbaren', 'to arrange, to agree', 'verb', NULL, 'Ich möchte einen neuen Termin vereinbaren.', 'I would like to arrange a new appointment.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.rechtzeitig', 'telc-deutsch-b1', 286, 'rechtzeitig', 'in time, early enough', 'adv', NULL, 'Wir sind rechtzeitig am Bahnhof angekommen.', 'We arrived at the station in time.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-feiertag', 'telc-deutsch-b1', 287, 'der Feiertag', 'public holiday', 'noun', 'die Feiertage', 'An Feiertagen haben die meisten Geschäfte geschlossen.', 'On public holidays most shops are closed.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-alltag', 'telc-deutsch-b1', 288, 'der Alltag', 'everyday life, daily routine', 'noun', 'der Alltag', 'Im Alltag habe ich leider wenig Zeit für Sport.', 'In everyday life I unfortunately have little time for sport.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-vergangenheit', 'telc-deutsch-b1', 289, 'die Vergangenheit', 'past', 'noun', 'die Vergangenheiten', 'In der Vergangenheit habe ich sehr viel gereist.', 'In the past I travelled a great deal.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.die-gegenwart', 'telc-deutsch-b1', 290, 'die Gegenwart', 'present (time)', 'noun', 'die Gegenwarten', 'In der Gegenwart ändert sich alles sehr schnell.', 'In the present everything changes very quickly.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.der-beginn', 'telc-deutsch-b1', 291, 'der Beginn', 'beginning, start', 'noun', 'die Beginne', 'Der Beginn der Veranstaltung wurde auf neunzehn Uhr verschoben.', 'The start of the event was moved to seven in the evening.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.regelmaessig', 'telc-deutsch-b1', 292, 'regelmäßig', 'regular, regularly', 'adj', NULL, 'Ich gehe regelmäßig zweimal pro Woche schwimmen.', 'I go swimming regularly twice a week.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.selten', 'telc-deutsch-b1', 293, 'selten', 'rarely, seldom', 'adv', NULL, 'So einen guten Film sehe ich selten.', 'I rarely see such a good film.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.inzwischen', 'telc-deutsch-b1', 294, 'inzwischen', 'meanwhile, by now', 'adv', NULL, 'Inzwischen hat sich die Lage wieder verbessert.', 'Meanwhile the situation has improved again.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.damals', 'telc-deutsch-b1', 295, 'damals', 'back then, at that time', 'adv', NULL, 'Damals hatten wir noch kein Internet zu Hause.', 'Back then we didn''t have the internet at home yet.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.demnaechst', 'telc-deutsch-b1', 296, 'demnächst', 'soon, shortly', 'adv', NULL, 'Demnächst ziehen wir in eine andere Stadt.', 'Soon we are moving to another city.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.vorher', 'telc-deutsch-b1', 297, 'vorher', 'beforehand, before', 'adv', NULL, 'Ruf mich bitte vorher an, wenn du kommst.', 'Please call me beforehand if you are coming.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.nachher', 'telc-deutsch-b1', 298, 'nachher', 'afterwards, later', 'adv', NULL, 'Nachher gehen wir noch etwas trinken.', 'Afterwards we''ll go and have a drink.', 'telc-deutsch-b1.vocab@v1'),
    ('telc-deutsch-b1.vocab.das-datum', 'telc-deutsch-b1', 299, 'das Datum', 'date', 'noun', 'die Daten', 'Bitte schreiben Sie das Datum auf das Formular.', 'Please write the date on the form.', 'telc-deutsch-b1.vocab@v1')
